// TestGPUPlacementParity asserts the Go port makes the exact decisions the
// Python T6b selector made (testdata generated by gen_gpu_placement_cases.py).
func TestGPUPlacementParity(t *testing.T) {
	raw, err := os.ReadFile("testdata/gpu_placement_cases.json")
	if err != nil {
		t.Fatal(err)
	}
	var fx struct {
		Cases []struct {
			Demand   GPUDemand       `json:"demand"`
			Caps     *GPUClusterCaps `json:"caps"`
			Prefer   string          `json:"prefer"`
			Expected GPUPlacement    `json:"expected"`
		} `json:"cases"`
	}
	if err := json.Unmarshal(raw, &fx); err != nil {
		t.Fatal(err)
	}
	if len(fx.Cases) < 100 {
		t.Fatalf("fixture too small: %d", len(fx.Cases))
	}
	for i, c := range fx.Cases {
		got := ChooseGPUPlacement(c.Demand, c.Caps, c.Prefer)
		if !reflect.DeepEqual(got, c.Expected) {
			t.Errorf("case %d demand=%+v caps=%+v prefer=%s\n got=%+v\nwant=%+v", i, c.Demand, c.Caps, c.Prefer, got, c.Expected)
		}
	}
}

func gpuNode(name string, labels map[string]string, alloc map[string]int64) corev1.Node {
	rl := corev1.ResourceList{}
	for k, v := range alloc {
		rl[corev1.ResourceName(k)] = *resource.NewQuantity(v, resource.DecimalSI)
	}
	return corev1.Node{ObjectMeta: metav1.ObjectMeta{Name: name, Labels: labels}, Status: corev1.NodeStatus{Allocatable: rl}}
}

func nodeObj(n corev1.Node) *corev1.Node { return &n }

func TestGPUCapsFromNodes(t *testing.T) {
	if GPUCapsFromNodes([]corev1.Node{gpuNode("cpu", nil, map[string]int64{"cpu": 8})}) != nil {
		t.Fatal("CPU-only cluster must yield nil caps")
	}
	nodes := []corev1.Node{
		gpuNode("ex", map[string]string{LabelDevicePluginConfig: "exclusive", LabelGFDProduct: "L40S"}, map[string]int64{"nvidia.com/gpu": 2}),
		gpuNode("ts8", map[string]string{LabelDevicePluginConfig: "time-sliced-8", LabelGFDMemoryMiB: "49152"}, map[string]int64{"nvidia.com/gpu": 8}),
		gpuNode("ts4", map[string]string{LabelDevicePluginConfig: "time-sliced-4", LabelGFDMemoryMiB: "81920"}, map[string]int64{"nvidia.com/gpu": 4}),
		gpuNode("mig", map[string]string{LabelMIGConfigState: "success", LabelGFDMIGStrategy: "mixed"},
			map[string]int64{"nvidia.com/mig-3g.40gb": 1, "nvidia.com/mig-1g.10gb": 2, "nvidia.com/mig-7g.80gb": 1}),
		gpuNode("mig-pending", map[string]string{LabelMIGConfigState: "pending"}, map[string]int64{"nvidia.com/mig-2g.20gb": 1}),
	}
	c := GPUCapsFromNodes(nodes)
	want := &GPUClusterCaps{Modes: []string{"whole", "time_slice", "mig"}, MIGProfiles: []string{"1g.10gb", "3g.40gb"},
		TimeSliceReplicas: 4, GPUMemoryGB: 48, HasExclusiveNodes: true}
	if !reflect.DeepEqual(c, want) {
		t.Fatalf("caps=%+v want %+v", c, want)
	}
}

func TestGPUCapsCacheTTLAndFailure(t *testing.T) {
	cs := fake.NewSimpleClientset()
	lists := 0
	fail := true
	cs.PrependReactor("list", "nodes", func(k8stesting.Action) (bool, runtime.Object, error) {
		lists++
		if fail {
			return true, nil, errors.New("forbidden")
		}
		return true, &corev1.NodeList{Items: []corev1.Node{
			gpuNode("n", map[string]string{LabelDevicePluginConfig: "exclusive"}, map[string]int64{"nvidia.com/gpu": 1})}}, nil
	})
	now := time.Unix(1000, 0)
	c := NewGPUCapsCache(cs)
	c.now = func() time.Time { return now }
	c.Refresh(context.Background())
	c.Refresh(context.Background())
	if lists != 1 || c.Snapshot() != nil {
		t.Fatalf("failure: lists=%d caps=%v (want 1 list, nil caps)", lists, c.Snapshot())
	}
	fail = false
	now = now.Add(DefaultGPUCapsTTL + time.Second)
	c.Refresh(context.Background())
	if lists != 2 || c.Snapshot() == nil || !c.Snapshot().HasExclusiveNodes {
		t.Fatalf("recovery: lists=%d caps=%+v", lists, c.Snapshot())
	}
}

// End-to-end through Submit: cluster caps drive the Job's GPU resources.
func TestK8sGPUPlacementApplied(t *testing.T) {
	cluster := []runtime.Object{
		nodeObj(gpuNode("mig", map[string]string{LabelMIGConfigState: "success"}, map[string]int64{"nvidia.com/mig-2g.20gb": 7})),
		nodeObj(gpuNode("ts", map[string]string{LabelDevicePluginConfig: "time-sliced-4", LabelGFDMemoryMiB: "143360"}, map[string]int64{"nvidia.com/gpu": 4})),
		nodeObj(gpuNode("ex", map[string]string{LabelDevicePluginConfig: "exclusive"}, map[string]int64{"nvidia.com/gpu": 1})),
	}
	cases := []struct {
		name    string
		gpu     GPURequest
		env     map[string]string
		resName string
		sel     map[string]string
	}{
		{"mig-fit", GPURequest{Count: 1}, map[string]string{EnvGPUVRAMMB: "16384"}, "nvidia.com/mig-2g.20gb", map[string]string{LabelMIGConfigState: "success"}},
		{"shareable-too-big-for-mig", GPURequest{Count: 1}, map[string]string{EnvGPUVRAMMB: "25000", EnvGPUShareable: "true"}, "nvidia.com/gpu", map[string]string{LabelDevicePluginConfig: "time-sliced-4"}},
		{"unknown-vram-whole", GPURequest{Count: 1}, nil, "nvidia.com/gpu", map[string]string{LabelDevicePluginConfig: "exclusive"}},
		{"explicit-mig-wins", GPURequest{Count: 1, MIGProfile: "1g.10gb"}, map[string]string{EnvGPUVRAMMB: "16384"}, "nvidia.com/mig-1g.10gb", nil},
		{"multi", GPURequest{Count: 2}, nil, "nvidia.com/gpu", map[string]string{LabelDevicePluginConfig: "exclusive"}},
	}
	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			cs := fake.NewSimpleClientset(cluster...)
			b := NewK8sBackend(cs, "tenant-7")
			_, job := submitK8s(t, b, &TaskSpec{Image: "x", GPU: tc.gpu, Env: tc.env})
			ps := job.Spec.Template.Spec
			if len(ps.Containers[0].Resources.Limits) != 1 {
				t.Fatalf("limits=%v", ps.Containers[0].Resources.Limits)
			}
			if _, ok := ps.Containers[0].Resources.Limits[corev1.ResourceName(tc.resName)]; !ok {
				t.Fatalf("limits=%v want %s", ps.Containers[0].Resources.Limits, tc.resName)
			}
			if len(tc.sel) == 0 && len(ps.NodeSelector) == 0 {
				return
			}
			if !reflect.DeepEqual(ps.NodeSelector, tc.sel) {
				t.Fatalf("nodeSelector=%v want %v", ps.NodeSelector, tc.sel)
			}
		})
	}
}

// Node list forbidden (no RBAC yet) → today's behaviour, Submit still works.
func TestK8sGPUPlacementDegradesOnListError(t *testing.T) {
	cs := fake.NewSimpleClientset()
	cs.PrependReactor("list", "nodes", func(k8stesting.Action) (bool, runtime.Object, error) {
		return true, nil, errors.New("nodes is forbidden")
	})
	b := NewK8sBackend(cs, "tenant-7")
	_, job := submitK8s(t, b, &TaskSpec{Image: "x", GPU: GPURequest{Count: 1}, Env: map[string]string{EnvGPUVRAMMB: "8000"}})
	ps := job.Spec.Template.Spec
	if q := ps.Containers[0].Resources.Limits[ResourceGPU]; q.Value() != 1 || len(ps.NodeSelector) != 0 {
		t.Fatalf("want whole nvidia.com/gpu:1 no selector, got limits=%v sel=%v", ps.Containers[0].Resources.Limits, ps.NodeSelector)
	}
}
